// Parse the stringified JSON from the 'input' field. For chatbot targets the input is { chatInput, metadata }.
// Pass through case_id + binary_check + rubric for downstream nodes via $('Eval Trigger').
const out = [];
for (const item of $input.all()) {
  const raw = item.json.input ?? item.json.Input;
  if (!raw) continue;
  let parsed;
  try { parsed = JSON.parse(raw); }
  catch (e) { console.error('input JSON parse error:', e.message); continue; }
  out.push({ json: { ...parsed, case_id: item.json.case_id } });
}
return out;

// Capture Target Output — flatten the live target's response so downstream nodes (Contract Check, Binary Check, Judge) can reference
// $json.output (the agent's textual reply) and $json.tool_calls (intermediate tool invocations, if exposed by the target).
//
// Convention for chatbot targets: the target workflow's last node returns at least { output: "<text>" }; tool_calls is optional and depends on whether the target surfaces them.

for (const item of $input.all()) {
  const j = item.json || {};
  // Pick up the agent's reply from common fields.
  let output = j.output ?? j.response ?? j.message ?? j.text ?? '';
  if (typeof output !== 'string') {
    try { output = JSON.stringify(output); } catch (e) { output = String(output); }
  }
  // Tool calls — target may expose as tool_calls, intermediateSteps, or tools_used.
  const toolCalls = j.tool_calls ?? j.intermediateSteps ?? j.tools_used ?? null;
  item.json.output = output;
  // Alias for case binary_check rules that reference field=actual_output (matches the writeback column name).
  item.json.actual_output = output;
  item.json.tool_calls = toolCalls;
}
return $input.all();

// Contract Check — runs the target-specific validator against $json.output.
// Validator function body is substituted at template generation time.
// For text-output chatbots, validator typically just checks output is a non-empty string.

function validateAgentOutput(raw) {
      // vc-chatbot returns plain text. Contract: non-empty string.
      if (typeof raw !== 'string') return { valid: false, parsed: raw, errors: ['output is not a string'] };
      if (raw.trim().length === 0) return { valid: false, parsed: raw, errors: ['output is empty'] };
      return { valid: true, parsed: raw, errors: [] };
    }

for (const item of $input.all()) {
  const result = validateAgentOutput(item.json.output);
  item.json.contract_valid = result.valid;
  item.json.contract_errors = result.errors.join('; ');
  item.json.parsed_output = result.parsed;
}
return $input.all();

// Binary Check Runner — agent-output layer.
// Reads $('Eval Trigger').item.json.binary_check (stringified JSON array of checks).
// Six kinds: regex, schema, enum-membership, invariant, rule-table, cross-reference.
// For sub-workflow mode, ctx also exposes tool_calls so rule-table checks can introspect tool invocations.

function getPath(obj, path) {
  if (!obj || !path) return undefined;
  return path.split('.').reduce((acc, key) => (acc == null ? acc : acc[key]), obj);
}

function extractTitleCaseBigrams(text) {
  if (typeof text !== 'string') return [];
  const matches = text.match(/[A-Z][a-z]+\s+[A-Z][a-z]+/g) || [];
  return matches.map(s => s.trim());
}

function runRegex(check, ctx) {
  const field = check.field;
  const target = (ctx[field] != null ? ctx[field] : getPath(ctx, field)) || '';
  const targetStr = typeof target === 'string' ? target : JSON.stringify(target);
  const patterns = (check.patterns || []).map(p => new RegExp(p, 'i'));
  if (check.must_not_match) {
    const matched = patterns.find(re => re.test(targetStr));
    return { passed: !matched, detail: matched ? 'matched forbidden pattern: ' + matched.source : '' };
  }
  if (check.must_match) {
    const allMatch = patterns.every(re => re.test(targetStr));
    return { passed: allMatch, detail: allMatch ? '' : 'one or more required patterns missing' };
  }
  return { passed: false, detail: 'regex check missing must_match/must_not_match flag' };
}

function runSchema(check, ctx) {
  if (check.validator === 'validate-agent-output') {
    const valid = ctx.contract_valid === true;
    return { passed: valid, detail: valid ? '' : (ctx.contract_errors || 'contract invalid') };
  }
  return { passed: false, detail: 'unknown schema validator: ' + check.validator };
}

function runEnumMembership(check, ctx) {
  const value = getPath(ctx.parsed_output || {}, check.path);
  const passed = (check.allowed || []).includes(value);
  return { passed, detail: passed ? '' : 'value ' + JSON.stringify(value) + ' not in allowed list' };
}

function runInvariant(check, ctx) {
  const parsed = ctx.parsed_output;
  if (!parsed) return { passed: false, detail: 'no parsed_output to evaluate invariant' };
  try {
    const fn = new Function('o', 'return ' + check.rule.replace(/([a-z_]+(?:\.[a-z_]+)+)/gi, (m) => 'o.' + m));
    const result = fn(parsed);
    return { passed: result === true, detail: result === true ? '' : 'invariant rule evaluated false: ' + check.rule };
  } catch (e) {
    return { passed: false, detail: 'invariant evaluation error: ' + e.message };
  }
}

function runRuleTable(check, ctx) {
  // Sub-workflow mode rule-table can reference tool_calls, output, parsed_output via free-form JS rule.
  if (check.rule) {
    try {
      const fn = new Function('output', 'tool_calls', 'parsed_output', 'contract_valid', 'return ' + check.rule);
      const result = fn(ctx.output, ctx.tool_calls, ctx.parsed_output, ctx.contract_valid);
      return { passed: result === true, detail: result === true ? '' : 'rule evaluated false: ' + check.rule };
    } catch (e) {
      return { passed: false, detail: 'rule evaluation error: ' + e.message };
    }
  }
  // Legacy key_paths/allowed_pairs form.
  const sources = (check.key_paths || []).map(p => {
    if (p.startsWith('input.')) return getPath(ctx, p.replace(/^input\./, ''));
    return getPath(ctx.parsed_output || {}, p);
  });
  const allowed = (check.allowed_pairs || []).some(pair => pair.every((v, i) => v === sources[i]));
  return { passed: allowed, detail: allowed ? '' : 'pair ' + JSON.stringify(sources) + ' not in allowed_pairs' };
}

function runCrossReference(check, ctx) {
  const sourceVal = getPath(ctx.parsed_output || {}, check.source_field) || ctx[check.source_field] || '';
  const STOP_STARTERS = new Set(['While','The','Her','His','When','If','Given','However','Although','Their','These','That','This','As','For','But','And','Or','Now','Here','There']);
  const stoplist = new Set(check.stoplist || []);
  let sourceTokens = extractTitleCaseBigrams(typeof sourceVal === 'string' ? sourceVal : JSON.stringify(sourceVal));
  sourceTokens = sourceTokens.filter(t => !stoplist.has(t) && !STOP_STARTERS.has(t.split(/\s+/)[0]));
  if (sourceTokens.length === 0) return { passed: true, detail: 'no proper-noun bigrams in source (after stoplist)' };
  const contextStr = (check.context_fields || []).map(p => {
    const v = p.startsWith('input.') ? ctx[p.replace(/^input\./, '')] : getPath(ctx, p);
    return typeof v === 'string' ? v : JSON.stringify(v || '');
  }).join(' ').toLowerCase();
  const missing = sourceTokens.filter(t => !contextStr.includes(t.toLowerCase()));
  return { passed: missing.length === 0, detail: missing.length === 0 ? '' : 'ungrounded tokens: ' + missing.join(', ') };
}

const RUNNERS = {
  'regex': runRegex,
  'schema': runSchema,
  'enum-membership': runEnumMembership,
  'invariant': runInvariant,
  'rule-table': runRuleTable,
  'cross-reference': runCrossReference,
};

for (const item of $input.all()) {
  const trigger = $('Eval Trigger').item.json;
  const inputCtx = $('Set Eval Inputs').item.json;
  const ctx = Object.assign({}, inputCtx, item.json);
  const checksRaw = trigger.binary_check;
  let checks = [];
  if (typeof checksRaw === 'string' && checksRaw.trim().length > 0) {
    try { checks = JSON.parse(checksRaw); } catch (e) { checks = []; }
  } else if (Array.isArray(checksRaw)) {
    checks = checksRaw;
  }
  const results = checks.map(c => {
    const runner = RUNNERS[c.kind];
    const r = runner ? runner(c, ctx) : { passed: false, detail: 'unknown kind: ' + c.kind };
    return { check_id: c.check_id, kind: c.kind, passed: r.passed, detail: r.detail };
  });
  item.json.binary_check_results_output = results;
  item.json.binary_violation_count_output = results.filter(r => r.passed === false).length;
}
return $input.all();

