// Aggregate Scores — positive-match rubric. Reads judge response { scores: [{ dimension, score, reasoning }] },
// computes smoke_passed (every dimension at-or-above its floor) and regression_passed (delta from golden_score).

function parseScores(text) {
  if (!text) return { scores: [] };
  const cleaned = String(text).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '');
  try {
    const obj = JSON.parse(cleaned);
    if (obj && Array.isArray(obj.scores)) return obj;
    return { scores: [] };
  } catch (e) {
    return { scores: [], parse_error: e.message, raw: cleaned.slice(0, 400) };
  }
}

function parseRubric(raw) {
  if (!raw) return [];
  if (Array.isArray(raw)) return raw;
  try { const r = JSON.parse(raw); return Array.isArray(r) ? r : []; } catch (e) { return []; }
}

function floorFor(rubric, dimension, defaultFloor) {
  const dim = rubric.find(r => r && r.dimension === dimension);
  if (dim && typeof dim.floor === 'number') return dim.floor;
  return defaultFloor;
}

function smokePass(scores, rubric, defaultFloor) {
  if (!Array.isArray(scores) || scores.length === 0) return false;
  for (const s of scores) {
    const floor = floorFor(rubric, s.dimension, defaultFloor);
    if (typeof s.score !== 'number' || s.score < floor) return false;
  }
  return true;
}

function regressionPass(scores, golden, defaultDelta) {
  if (!golden || !Array.isArray(golden) || golden.length === 0) return null;
  for (const s of scores) {
    const g = golden.find(x => x && x.dimension === s.dimension);
    if (!g || typeof g.score !== 'number') continue;
    if ((s.score - g.score) < defaultDelta) return false;
  }
  return true;
}

const DEFAULT_FLOOR = 3;
const DEFAULT_REGRESSION_DELTA = -0.5;

for (const item of $input.all()) {
  const trigger = $('Eval Trigger').item.json;
  const captured = $('Capture Target Output').item.json;
  const contract = $('Contract Check').item.json;
  const judgeRawText = $('Judge Output Chain').item.json.text;
  const judge = parseScores(judgeRawText);
  const scores = judge.scores || [];
  const rubric = parseRubric(trigger.rubric);
  const golden = parseRubric(trigger.golden_score);

  const smoke = smokePass(scores, rubric, DEFAULT_FLOOR) && contract.contract_valid !== false;
  const regression = regressionPass(scores, golden, DEFAULT_REGRESSION_DELTA);

  const ts = Date.now();
  const rand = Math.random().toString(36).slice(2, 8);
  const runId = trigger.run_id || ('run-' + ts + '-' + rand);
  const timestamp = new Date().toISOString();

  // Binary check results — pull from Binary Check Output directly, since Judge Output Chain (chainLlm)
  // drops upstream item.json fields and only forwards { text }.
  const binaryNode = $('Binary Check Output').item.json;
  const binaryResults = binaryNode.binary_check_results_output || [];
  const binaryViolationCount = binaryNode.binary_violation_count_output ?? binaryResults.filter(r => r.passed === false).length;

  item.json.case_id = trigger.case_id;
  item.json.actual_output = captured.output;
  item.json.contract_valid = contract.contract_valid;
  item.json.contract_errors = contract.contract_errors;
  item.json.binary_check_results = JSON.stringify(binaryResults);
  item.json.binary_violation_count = binaryViolationCount;
  item.json.dimension_scores = JSON.stringify(scores);
  item.json.smoke_passed = smoke;
  item.json.regression_passed = regression;
  item.json.judge_raw = judgeRawText;
  item.json.model_variant = 'vc-chatbot-stream/baseline-2026-05-03';
  item.json.judge_model = 'anthropic/claude-sonnet-4.6';
  item.json.run_id = runId;
  item.json.timestamp = timestamp;
}

return $input.all();
